function homeCtrl(n,t){function i(){t.getData("GET","DocumentoElectronico/GetByStatus/?json="+JSON.stringify({tipo:3}),null,!0).then(t=>{t.code=="1"&&(n.docs=JSON.parse(t.payload)[0],$("#comprobantesErroneosModal").modal("show"))}).catch(n=>{console.log(n)})}n.docs=[];n.init=()=>{t.getData("get","Dashboard/",null,!0).then(function(t){if(t.id==0){toast.toastr("warning",t.message,t.titleSms);return}let i=JSON.parse(t.payload)[0];n.cantidad=i[0]}).catch(n=>{console.log(n)}),i()};n.init();n.fixDocs=()=>{location.href="/DocumentoElectronico/Index?tipo=3"}}app.controller("homeCtrl",homeCtrl);homeCtrl.$inject=["$scope","mainService","$interval"];